{"src/exportCsv.mjs":"/** rows为对象数组，返回可用于下载的字符串。 */
export function exportCsv(rows) {
  const list = Array.isArray(rows) ? rows : [];

  // 收集所有出现过的字段名，保持首次出现顺序，避免不同对象键不一致时丢列
  const headers = [];
  const seen = new Set();
  for (const row of list) {
    if (row && typeof row === "object") {
      for (const key of Object.keys(row)) {
        if (!seen.has(key)) {
          seen.add(key);
          headers.push(key);
        }
      }
    }
  }

  const escapeField = (value) => {
    let text;
    if (value === null || value === undefined) {
      text = "";
    } else if (typeof value === "object") {
      // 外部填写内容可能包含对象/数组，统一序列化，避免出现 [object Object]
      try {
        text = JSON.stringify(value);
      } catch {
        text = String(value);
      }
    } else {
      text = String(value);
    }

    // 含逗号、双引号、换行（CR/LF）或首尾空白时用双引号包裹，内部双引号翻倍
    if (/[",\r\n]/.test(text) || /^\s|\s$/.test(text)) {
      return '"' + text.replace(/"/g, '""') + '"';
    }
    return text;
  };

  const lines = [];
  if (headers.length > 0) {
    lines.push(headers.map(escapeField).join(","));
    for (const row of list) {
      const record = row && typeof row === "object" ? row : {};
      lines.push(headers.map((key) => escapeField(record[key])).join(","));
    }
  }

  // 使用 CRLF 换行并加 UTF-8 BOM，提升 Excel 等表格软件打开时的兼容性
  return "\uFEFF" + lines.join("\r\n") + (lines.length > 0 ? "\r\n" : "");
}
